String h = ctx.historique_protection;
if (h != null) {
  List liste = new ArrayList();
  for (String p : h.splitOnToken(' ; ')) {
    int i = p.indexOf(' : ');
    if (i > 0) {
      liste.add(['date': p.substring(0, i).trim(), 'type': p.substring(i + 3).trim()]);
    }
  }
  ctx.protections = liste;
}
